-- Original: server/internal/quest/upstream/projecteq/skyshrine/Sentry_Kale.pl (sha256 e410f9a0eddf9616e13c96297c2581701ee26994aa0e9b04b3a3a52a30058465)
-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- The original Friend of the Kin route remains available without a Velium Retrieval prerequisite. Velium Retrieval added by the backlog batch. P99 does not publish bracer odds: retain ProjectEQ 2/3 as an approximation; 4pp is the documented coin reward.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Ah outsiders, I have heard word of your travel here. Perhaps you wish to become a [friend of the kin]?")
  elseif e.message:findi("friend of the kin") then
    e.self:Say("We have received word from Wenglawks of Kael that he has information concerning a spy amongst us. For 100 platinum, he has offered us the information. Take this note to Wenglawks and rid us of this traitor.")
    e.other:SummonItem(29068)
  elseif e.message:findi("sentinel") then
    e.self:Say("It was not too long ago that I was merely a chunk of walking velium in the eyes of most who traveled through the shrine. However that golem was in fact one of my sentinels used to keep my identity secluded, and took on the tasks that I gave it. However, there has been a problem recently with our supplies, and I have had to take it offline until further notice.")
  elseif e.message:findi("problem") then
    e.self:Say("As you may have noticed, there are a great deal of golems and gargoyles within the shrine that consist of velium. These are our guards and they serve us well, however with extended use of these creatures comes extensive repair needed. It is because of this necessity to keep our sentries and lookouts working well that we require a great deal of velium ore stocked and ready for use. Unfortunately, our supplies have been running thin and we are in need of a new shipment of ore.")
  elseif e.message:findi("supplies") then
    e.self:Say("I may have been wrong in my initial thoughts about your race, " .. e.other:GetRaceName() .. ". You may just prove to be worth my time. Take this note now and find Ungdin. Please hurry and remember to keep this information to yourself.")
    e.other:SummonItem(1725)
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 29065 }) then
    e.self:Say("You have done us a great service, " .. e.other:GetCleanName() .. ". I would like you to have this small token of our gratitude. A venerable wurm allowed us to grace this piece of armor with his teeth when he passed on, wear it well.")
    e.other:SummonItem(29050)
    e.other:AddEXP(32500)
    e.other:Faction(430, 10, 0)
    e.other:Faction(436, 10, 0)
    e.other:Faction(448, -30, 0)
  elseif item_lib.check_turn_in(e.trade, { item1 = 29064 }) then
    e.self:Say("You've returned, and with the shipment of ore intact! It was wise to send you out on that mission, " .. e.other:GetCleanName() .. ", and I'm glad you did not fail. If you're looking for more assignments to do, I may have something that is just right for you. If you're interested in it, just let me know and we'll talk.")
    e.other:AddEXP(12500)
    e.other:Faction(436, 10, 0)
    e.other:Faction(430, 10, 0)
    e.other:Faction(448, -30, 0)
    e.other:AddMoneyToPP(0, 0, 0, 4, true)
    if math.random(1, 3) <= 2 then e.other:SummonItem(1727) end
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
